import 'package:flutter/material.dart';import 'package:provider/provider.dart';import '../../providers/finance_provider.dart';import '../../utils/helpers.dart';
class ReportScreen extends StatelessWidget{const ReportScreen({super.key});@override Widget build(BuildContext c){final f=c.watch<FinanceProvider>();final total=f.totalIncome+f.totalExpense;final cats=<String,double>{};for(final e in f.expenses){cats[e.category]=(cats[e.category]??0)+e.amount;}final highest=cats.entries.isEmpty?null:(cats.entries.toList()..sort((a,b)=>b.value.compareTo(a.value))).first;return SafeArea(child:ListView(padding:const EdgeInsets.all(16),children:[Text('Financial report',style:Theme.of(c).textTheme.headlineSmall),const SizedBox(height:16),SegmentedButton<String>(segments:const[ButtonSegment(value:'Month',label:Text('This month')),ButtonSegment(value:'Year',label:Text('This year'))],selected:const{'Month'},onSelectionChanged:(_)=>{}),const SizedBox(height:20),Row(children:[Expanded(child:_metric(c,'Income',f.totalIncome,Colors.green)),const SizedBox(width:12),Expanded(child:_metric(c,'Expense',f.totalExpense,Colors.red))]),const SizedBox(height:12),_metric(c,'Balance',f.balance,Theme.of(c).colorScheme.primary),const SizedBox(height:28),Text('Expense categories',style:Theme.of(c).textTheme.titleLarge),const SizedBox(height:12),if(cats.isEmpty)const Text('Add expenses to see your category report.') else ...cats.entries.map((e){final p=e.value/(f.totalExpense==0?1:f.totalExpense);return Padding(padding:const EdgeInsets.only(bottom:14),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[Text(e.key),Text('${(p*100).round()}% · ${formatCurrency(e.value)}')]),const SizedBox(height:6),LinearProgressIndicator(value:p)]));}),const SizedBox(height:12),Text('Highest expense category: ${highest?.key??'—'}',style:Theme.of(c).textTheme.titleMedium),Text('Average daily expense: ${formatCurrency(f.totalExpense/30)}') ]));}Widget _metric(BuildContext c,String label,double value,Color color)=>Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(label),const SizedBox(height:6),Text(formatCurrency(value),style:TextStyle(fontWeight:FontWeight.bold,color:color))])));}
